def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])

    # Find background color (most frequent)
    counter = Counter()
    for row in grid:
        for cell in row:
            counter[cell] += 1
    background = max(counter, key=counter.get)

    out = [row[:] for row in grid]

    # For each color other than background, find all pixels and project diagonally
    for color in counter:
        if color == background:
            continue

        pixels = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    pixels.append((r, c))

        # Project each pixel diagonally down-right
        for pr, pc in pixels:
            arc_r, arc_c = pr, pc
            while True:
                arc_r += 1
                arc_c += 1
                if arc_r >= h or arc_c >= w:
                    break
                if out[arc_r][arc_c] == background:
                    out[arc_r][arc_c] = color
                else:
                    break

    return out
