def transform(grid):
    all_cells = [cell for row in grid for cell in row]
    from collections import Counter

    bg_count = Counter(all_cells)
    bg = max(bg_count, key=bg_count.get)

    h, w = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    for color in set(all_cells):
        if color == bg:
            continue

        # For each pixel of this color, extend diagonally down-right
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    # Extend down-right
                    for k in range(1, min(h-r, w-c)):
                        nr, nc = r+k, c+k
                        if 0 <= nr < h and 0 <= nc < w and output[nr][nc] == bg:
                            output[nr][nc] = color
                        else:
                            break

    return output
